 for(auto mutation:std::vector<std::string>{"identity","standing","absence","space","clock","peer"}){Run r(root);r.begin();r.provider.edit([&]{r.provider.change=[&](auto& b){if(mutation=="identity")b.identity.session="other";if(mutation=="standing")b.identity.standing="other";if(mutation=="absence")b.absent=true;if(mutation=="space")std::get<mb::c1::TrackerObservation>(b.frames[0].envelope).coordinate_space.revision=2;if(mutation=="clock")std::get<mb::c1::TrackerObservation>(b.frames[0].envelope).clock_id="other";if(mutation=="peer")b.frames[0].peer="other";};});std::this_thread::sleep_for(std::chrono::milliseconds(30));r.session->tick();CHECK(r.session->phase()=="INSPECT_ONLY");CHECK(mb::readConfigBytes(r.seed.path)==r.seed.original);passed();}
