 {Run r(root);auto review=r.review();CHECK(review.at("criteria")=="NOT_ADOPTED"&&review.at("reason")=="PHYSICAL_CRITERIA_NOT_ADOPTED");for(auto& member:review.at("members"))CHECK(member.at("eligible")==false&&member.at("selected")==false);rejected(r.prepare(review),"PHYSICAL_CRITERIA_NOT_ADOPTED");CHECK(!std::filesystem::exists(r.seed.env.draftRoot)&&mb::readConfigBytes(r.seed.path)==r.seed.original);passed();}
 {Run r(root);auto authority=std::make_shared<Authority>();r.seed.env.outputApprovalAuthority=authority;r.reset();auto review=r.review();auto p=r.prepare(review);CHECK(p.at("status")=="OUTPUT_PREPARED");auto candidate=mb::readConfigBytes(std::filesystem::u8path(p.at("candidate_path").get<std::string>()));auto before=lc::Json::parse(r.seed.original),after=lc::Json::parse(candidate);CHECK(after.at("mapping_revision")==before.at("mapping_revision").get<unsigned>()+1);for(std::size_t i=0;i<after["mappings"].size();++i){CHECK(after["mappings"][i]["world"]==before["mappings"][i]["world"]&&after["mappings"][i]["mount"]==before["mappings"][i]["mount"]);if(after["mappings"][i]["source_id"]=="pico"&&after["mappings"][i]["device_id"]=="device")CHECK(after["mappings"][i]["space_approved"]==true);else CHECK(after["mappings"][i]["space_approved"]==before["mappings"][i]["space_approved"]);}auto expected=before;expected["mapping_revision"]=before.at("mapping_revision").get<unsigned>()+1;for(auto& member:expected["mappings"])if(member["source_id"]=="pico"&&member["device_id"]=="device")member["space_approved"]=true;CHECK(after==expected);auto commit=r.commit(p);auto out=r.execute(commit);CHECK(out.at("status")=="SAVED"&&out.at("action")=="OUTPUT_APPROVAL"&&r.session->solveCalls()==0&&r.session->commitCalls()==1);CHECK(mb::readConfigBytes(r.seed.path)==candidate);CHECK(r.execute(commit).at("replayed")==true&&r.session->commitCalls()==1);passed();}
 for(auto kind:std::vector<std::string>{"readonly","empty","foreign","duplicate","expired","scope","changed","config","token","candidate"}){Run r(root);auto authority=std::make_shared<Authority>();r.seed.env.outputApprovalAuthority=authority;r.reset();auto review=r.review(kind=="readonly");if(kind=="readonly")rejected(r.prepare(review),"READONLY_APPROVAL_REJECTED");else if(kind=="empty")rejected(r.prepare(review,lc::Json::array()),"APPROVAL_SELECTION_REQUIRED");else if(kind=="foreign")rejected(r.prepare(review,lc::Json::array({"sibling"})),"APPROVAL_MEMBER_INELIGIBLE");else if(kind=="duplicate")rejected(r.prepare(review,lc::Json::array({"device","device"})),"APPROVAL_DUPLICATE_MEMBER");else if(kind=="expired"){authority->expired=true;rejected(r.prepare(review),"PHYSICAL_EVIDENCE_MISSING_OR_EXPIRED");}else if(kind=="scope"){authority->expectedFrame="foreign";rejected(r.prepare(review),"SYNTHETIC_EVIDENCE_SCOPE_MISMATCH");}else if(kind=="changed"){authority->changed=true;rejected(r.prepare(review),"APPROVAL_CRITERIA_CHANGED_REVIEW_REQUIRED");}else{auto p=r.prepare(review);CHECK(p.at("status")=="OUTPUT_PREPARED");auto commit=r.commit(p);if(kind=="config"){std::ofstream f(r.seed.path,std::ios::app);f<<" ";f.close();auto out=r.execute(commit);CHECK(out.at("status")=="REJECTED");}if(kind=="token"){commit["review_token"]="foreign";rejected(r.execute(commit),"OUTPUT_COMMIT_NOT_PREPARED");}if(kind=="candidate"){std::ofstream f(std::filesystem::u8path(p.at("candidate_path").get<std::string>()),std::ios::app);f<<" ";f.close();CHECK(r.execute(commit).at("status")=="REJECTED");}}
  if(kind!="config")CHECK(mb::readConfigBytes(r.seed.path)==r.seed.original);passed();}
 {Run r(root);auto authority=std::make_shared<Authority>();r.seed.env.outputApprovalAuthority=authority;r.seed.env.afterReplace=[](){throw std::runtime_error("TEST_AFTER_REPLACE");};r.reset();auto review=r.review();auto p=r.prepare(review);auto candidate=mb::readConfigBytes(std::filesystem::u8path(p.at("candidate_path").get<std::string>()));CHECK(r.execute(r.commit(p)).at("status")=="UNKNOWN"&&mb::readConfigBytes(r.seed.path)==candidate);passed();}
 {Run r(root);auto authority=std::make_shared<Authority>();r.seed.env.outputApprovalAuthority=authority;r.reset();auto review=r.review();auto p=r.prepare(review);CHECK(p.at("status")=="OUTPUT_PREPARED");auto candidate=mb::readConfigBytes(std::filesystem::u8path(p.at("candidate_path").get<std::string>()));r.provider.edit([&]{r.provider.stepNs=400000000;});auto limit=std::chrono::steady_clock::now()+std::chrono::seconds(5);while(r.seed.time.load()<p.at("review_deadline_ns").get<std::int64_t>()){CHECK(std::chrono::steady_clock::now()<limit);std::this_thread::sleep_for(std::chrono::milliseconds(2));}rejected(r.execute(r.commit(p)),"APPROVAL_REVIEW_TOKEN_EXPIRED");auto again=r.prepare(review);CHECK(again.at("status")=="OUTPUT_PREPARED"&&again.at("review_token")!=p.at("review_token")&&again.at("candidate_sha256")==p.at("candidate_sha256"));CHECK(r.execute(r.commit(again)).at("status")=="SAVED"&&mb::readConfigBytes(r.seed.path)==candidate&&r.session->commitCalls()==1);passed();}
